"""DADS/SADS result display tab."""

from __future__ import annotations

from PyQt5.QtWidgets import (
    QComboBox,
    QFileDialog,
    QHBoxLayout,
    QLabel,
    QMessageBox,
    QPlainTextEdit,
    QPushButton,
    QTableWidget,
    QTableWidgetItem,
    QVBoxLayout,
    QWidget,
)
from matplotlib.backends.backend_qt5agg import (
    FigureCanvasQTAgg as FigureCanvas,
    NavigationToolbar2QT as NavigationToolbar,
)
from matplotlib.figure import Figure

from .ads_config import ADSResult
from .ads_export import export_ads_bundle
from .result_views import (
    ads_result_to_plot_arrays,
    ads_result_to_report_text,
    ads_result_to_spectra_table,
    ads_result_to_summary_rows,
)


class CalcDADSResultTab(QWidget):
    """Display associated spectra and reconstructed energy scans."""

    def __init__(self, parent=None) -> None:
        super().__init__(parent)
        self.result: ADSResult | None = None
        self._plot_data = {"spectra": [], "fits": []}
        self._create_ui()
        self.clear_result()

    def _create_ui(self) -> None:
        root = QVBoxLayout(self)

        self.summary_table = QTableWidget(0, 2, self)
        self.summary_table.setHorizontalHeaderLabels(("Name", "Value"))
        self.summary_table.setEditTriggers(QTableWidget.NoEditTriggers)
        root.addWidget(self.summary_table)

        self.spectra_table = QTableWidget(0, 0, self)
        self.spectra_table.setEditTriggers(QTableWidget.NoEditTriggers)
        root.addWidget(self.spectra_table)

        selector_row = QHBoxLayout()
        selector_row.addWidget(QLabel("Energy scan", self))
        self.time_combo = QComboBox(self)
        self.time_combo.currentIndexChanged.connect(self._update_plot)
        selector_row.addWidget(self.time_combo)
        selector_row.addStretch()

        self.export_button = QPushButton("Export results...", self)
        self.export_button.setEnabled(False)
        self.export_button.clicked.connect(self.export_results_dialog)
        selector_row.addWidget(self.export_button)
        root.addLayout(selector_row)

        self.figure = Figure(figsize=(9, 7))
        self.spectra_axis = self.figure.add_subplot(311)
        self.fit_axis = self.figure.add_subplot(312)
        self.residual_axis = self.figure.add_subplot(
            313,
            sharex=self.fit_axis,
        )
        self.canvas = FigureCanvas(self.figure)
        self.navigation_toolbar = NavigationToolbar(self.canvas, self)
        root.addWidget(self.navigation_toolbar)
        root.addWidget(self.canvas)

        self.report_view = QPlainTextEdit(self)
        self.report_view.setReadOnly(True)
        root.addWidget(self.report_view)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   

    def clear_result(self) -> None:
        self.result = None
        self._plot_data = {"spectra": [], "fits": []}
        self.summary_table.setRowCount(0)
        self.spectra_table.clear()
        self.spectra_table.setRowCount(0)
        self.spectra_table.setColumnCount(0)
        self.time_combo.clear()
        self.report_view.clear()
        self.export_button.setEnabled(False)
        self._update_plot()

    def set_result(self, result: ADSResult) -> None:
        if not isinstance(result, ADSResult):
            raise TypeError("result must be an ADSResult.")
        self.result = result
        self._plot_data = ads_result_to_plot_arrays(result)
        self._populate_summary(result)
        self._populate_spectra(result)
        self._populate_times()
        self.report_view.setPlainText(ads_result_to_report_text(result))
        self.export_button.setEnabled(True)
        self._update_plot()

    def export_results_dialog(self) -> None:
        if self.result is None:
            return

        directory = QFileDialog.getExistingDirectory(
            self, "Export ADS results"
        )

        if not directory:
            return

        try:
            export_ads_bundle(self.result, 
                              directory, figure=self.figure,
                              figure_formats=("png", "pdf"))
        except FileExistsError as exc:
            answer = QMessageBox.question(
                self, "Overwrite export files?",
                f"{exc}\nOverwrite the existing ADS export bundle?",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No
            )
            if answer != QMessageBox.Yes:
                return

            try:
                export_ads_bundle(self.result, directory,
                                  figure=self.figure, figure_formats=("png", "pdf"),
                                  overwrite=True)
            except Exception as retry_exc:
                QMessageBox.critical(
                    self, "Export failed", str(retry_exc)
                )
        except Exception as exc:
            QMessageBox.critical(self, "Export failed", str(exc))

    def _populate_summary(self, result: ADSResult) -> None:
        rows = ads_result_to_summary_rows(result)
        self.summary_table.setRowCount(len(rows))
        for row, entry in enumerate(rows):
            self.summary_table.setItem(
                row, 0, QTableWidgetItem(str(entry["name"]))
            )
            self.summary_table.setItem(
                row, 1, QTableWidgetItem(str(entry["value"]))
            )

    def _populate_spectra(self, result: ADSResult) -> None:
        table = ads_result_to_spectra_table(result)
        columns = table["columns"]
        rows = table["rows"]
        self.spectra_table.clear()
        self.spectra_table.setColumnCount(len(columns))
        self.spectra_table.setRowCount(len(rows))
        self.spectra_table.setHorizontalHeaderLabels(columns)
        for row_index, row_values in enumerate(rows):
            for column, value in enumerate(row_values):
                self.spectra_table.setItem(
                    row_index,
                    column,
                    QTableWidgetItem(f"{value:.8g}"),
                )

    def _populate_times(self) -> None:
        self.time_combo.clear()
        for entry in self._plot_data["fits"]:
            self.time_combo.addItem(
                f"t={entry['time']:g}",
                entry["time_index"],
            )

    def _update_plot(self) -> None:
        self.spectra_axis.clear()
        self.fit_axis.clear()
        self.residual_axis.clear()

        for entry in self._plot_data["spectra"]:
            if entry["spectrum_eps"] is None:
                self.spectra_axis.plot(
                    entry["energy"],
                    entry["spectrum"],
                    label=entry["name"],
                )
            else:
                self.spectra_axis.errorbar(
                    entry["energy"],
                    entry["spectrum"],
                    yerr=entry["spectrum_eps"],
                    label=entry["name"],
                    fmt="o-",
                )

        index = self.time_combo.currentIndex()
        if 0 <= index < len(self._plot_data["fits"]):
            entry = self._plot_data["fits"][index]
            self.fit_axis.errorbar(
                entry["energy"],
                entry["intensity"],
                yerr=entry["eps"],
                fmt="o",
                label="Data",
            )
            self.fit_axis.plot(
                entry["energy"],
                entry["fit"],
                label="Reconstruction",
            )
            self.residual_axis.errorbar(
                entry["energy"],
                entry["residual"],
                yerr=entry["eps"],
                fmt="o",
            )
            self.residual_axis.axhline(0.0, color="black", linewidth=0.8)
            self.fit_axis.legend()

        if self._plot_data["spectra"]:
            self.spectra_axis.legend()
        self.spectra_axis.set_ylabel("Associated spectrum")
        self.fit_axis.set_ylabel("Intensity")
        self.residual_axis.set_ylabel("Residual")
        self.residual_axis.set_xlabel("Energy")
        self.figure.tight_layout()
        self.canvas.draw_idle()
